    original_pine = '/*backtest\nstart: 2022-12-29 00:00:00\nend: 2024-01-04 00:00:00\nperiod: 1d\nbasePeriod: 1h\nexchanges: [{"eid":"Futures_Binance","currency":"BTC_USDT"}]\n*/\n\n//@version=2\n\nstrategy(title = "Ultimate Moving Average Strategy", shorttitle = "UMA Strategy", overlay = true)\n\n//Created by user ChrisMoody 4-24-2014\n//Converted to strategy by Virtual_Machinist 7-11-2018\n//Plots The Majority of Moving Averages\n//Defaults to Current Chart Time Frame --- But Can Be Changed to Higher Or Lower Time Frames\n//2nd MA Capability with Show Crosses Feature\n\n//inputs\nsrc = close\nuseCurrentRes = input(true, title="Use Current Chart Resolution?")\nresCustom = input(title="Use Different Timeframe? Uncheck Box Above",  defval="D")\nlen = input(20, title="Moving Average Length - LookBack Period")\natype = input(1,minval=1,maxval=7,title="1=SMA, 2=EMA, 3=WMA, 4=HullMA, 5=VWMA, 6=RMA, 7=TEMA")\ncc = input(true,title="Change Color Based On Direction?")\nsmoothe = input(2, minval=1, maxval=10, title="Color Smoothing - 1 = No Smoothing")\ndoma2 = input(false, title="Optional 2nd Moving Average")\nlen2 = input(50, title="Moving Average Length - Optional 2nd MA")\natype2 = input(1,minval=1,maxval=7,title="1=SMA, 2=EMA, 3=WMA, 4=HullMA, 5=VWMA, 6=RMA, 7=TEMA")\ncc2 = input(true,title="Change Color Based On Direction 2nd MA?")\nwarn = input(false, title="***You Can Turn On The Show Dots Parameter Below Without Plotting 2nd MA to See Crosses***")\nwarn2 = input(false, title="***If Using Cross Feature W/O Plotting 2ndMA - Make Sure 2ndMA Parameters are Set Correctly***")\nsd = input(false, title="Show Dots on Cross of Both MA\'s")\n\nuseStop     = input(defval = true, title = "Use Trailing Stop?")\nslPoints    = input(defval = 200, title = "Stop Loss Trail Points", minval = 1)\nslOffset    = input(defval = 400, title = "Stop Loss Trail Offset", minval = 1)\n\nres = useCurrentRes ? timeframe.period : resCustom\n//hull ma definition\nhullma = wma(2*wma(src, len/2)-wma(src, len), round(sqrt(len)))\n//TEMA definition\nema1 = ema(src, len)\nema2 = ema(ema1, len)\nema3 = ema(ema2, len)\ntema = 3 * (ema1 - ema2) + ema3\n\navg = atype == 1 ? sma(src,len) : atype == 2 ? ema(src,len) : atype == 3 ? wma(src,len) : atype == 4 ? hullma : atype == 5 ? vwma(src, len) : atype == 6 ? rma(src,len) : tema\n//2nd Ma - hull ma definition\nhullma2 = wma(2*wma(src, len2/2)-wma(src, len2), round(sqrt(len2)))\n//2nd MA TEMA definition\nsema1 = ema(src, len2)\nsema2 = ema(sema1, len2)\nsema3 = ema(sema2, len2)\nstema = 3 * (sema1 - sema2) + sema3\n\navg2 = atype2 == 1 ? sma(src,len2) : atype2 == 2 ? ema(src,len2) : atype2 == 3 ? wma(src,len2) : atype2 == 4 ? hullma2 : atype2 == 5 ? vwma(src, len2) : atype2 == 6 ? rma(src,len2) : tema\n\nout = avg \nout_two = avg2\n\nout1 = request.security(syminfo.tickerid, res, out)\nout2 = request.security(syminfo.tickerid, res, out_two)\n\nma_up = out1 >= out1[smoothe]\nma_down = out1 < out1[smoothe]\n\ncol = cc ? ma_up ? lime : ma_down ? red : aqua : aqua\ncol2 = cc2 ? ma_up ? lime : ma_down ? red : aqua : aqua\n\ncircleYPosition = out2\n\nplot(out1, title="Multi-Timeframe Moving Avg", style=line, linewidth=4, color = col)\nplot(doma2 and out2 ? out2 : na, title="2nd Multi-TimeFrame Moving Average", style=circles, linewidth=4, color=col2)\nplot(sd and cross(out1, out2) ? circleYPosition : na,style=cross, linewidth=5, color=yellow)\n\n// Strategy conditions\n\nlongCond    = ma_up\nshortCond   = ma_down\n// entries and base exit\nstrategy.entry("long", strategy.long, when = longCond)\nstrategy.entry("short", strategy.short, when = shortCond)\n\nif (useStop)\n    strategy.exit("XL", from_entry = "long", trail_points = slPoints, trail_offset = slOffset)\n    strategy.exit("XS", from_entry = "short", trail_points = slPoints, trail_offset = slOffset)\n// not sure needed, but just incase..\nstrategy.exit("XL", from_entry = "long", when = shortCond)\nstrategy.exit("XS", from_entry = "short", when = longCond)'

